    {
      "@type": "Question",
      "name": "What is a pharmaceutical excipient?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "An inactive ingredient in a formulation that performs a function such as filling, binding, disintegrating, lubricating, coating or solubilising. It is not therapeutically active but it determines whether the product manufactures and performs correctly."
      }
    },
    {
      "@type": "Question",
      "name": "Is a compendial grade excipient enough?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Not usually. Compendial compliance is a minimum. Particle size, bulk and tapped density, moisture and surface area frequently sit outside the monograph and are often what decides performance in your blend."
      }
    },
    {
      "@type": "Question",
      "name": "Are excipients made to the same GMP standard as APIs?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Often not. Many excipients are produced in large volumes for non-pharmaceutical industries, with pharmaceutical grade as a segregated portion. IPEC-PQG certification is the excipient specific standard worth asking for."
      }
    },
    {
      "@type": "Question",
      "name": "Can you supply excipients and APIs together?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, though they are assessed differently. Excipient selection starts from what the material must do in the formulation, which is a different question from the one an API specification answers."
      }
    }
  ]
